from taf.rfrl.csv4all.resources.node.uboot_downgrade.uboot import CSV4ALLUboot
from taf.rfrl.csv4all.resources.test_cases import UpgradeTest
from taf.rfrl.csv4all.resources.test_cases.exceptions import TestFailedOnTeardownError, TestExecutionFailed, \
    RecoveryAttemptFailedError
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, wrapper_decorator, function_wrapper
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError, NotAllOperationsSucceed
from taf.rfrl.csv4all.resources.utilities.test_global_constants import KPI_PER_TEST_CASE
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, verify_function_x_times
from taf.rfrl.csv4all.resources.utilities.wft import CSV4ALLWft
from taf.rfrl.csv4all.resources.airphone.wts import WTS


class ActivationResetTest(UpgradeTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 stop_test_after_fail: bool = False,
                 artifactory_location: Optional[str] = "espoo2", package_suffix: Optional[str] = "A54",
                 l3_call_method: Optional[callable] = None, yaft_path: Optional[str] = "/home/ute",
                 virtualenv_dir: str = None, detailed_console_log: bool = True, collect_passed_logs: int = 0,
                 configure_wts: bool = False, force_fw_upgrade: bool = False, software_precheck: bool = False,
                 diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, calculate_kpi, kpi_targets,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment,
                         sw_build, topology, use_external_storage, download_path, True, stop_test_after_fail,
                         artifactory_location, package_suffix, l3_call_method,
                         False, yaft_path, virtualenv_dir, detailed_console_log,
                         collect_passed_logs=collect_passed_logs, diagnostic_check=diagnostic_check)
        self.wft = CSV4ALLWft(artifactory_location, package_suffix, "T1")
        self.uboot = CSV4ALLUboot()
        self.uuf_case_type = "activation_reset"
        self.kpi_to_calculate = KPI_PER_TEST_CASE.get("Upgrade")
        self.restore_sw = True
        self.configure_wts = configure_wts
        self.wts = None
        self.force_fw_upgrade = force_fw_upgrade
        self.software_precheck = software_precheck

    def run_test(self):
        try:
            self.run_setup()
            self.execute_test_in_loop()
            if any(nodes_results != "passed" for nodes_results in self.test_results.values()):
                raise TestExecutionFailed()
        except (FatalError, RecoveryAttemptFailedError):
            self.restore_sw = False
            raise
        finally:
            if self.report_to_rp:
                self.report_results()
            if self.configure_wts and self.wts:
                self.teardown_wts()
            self.run_teardown()

    def test_setup(self):
        super().test_setup()
        self.verify_active_sw()
        if self.configure_wts:
            self.setup_wts()
        if self.force_fw_upgrade:
            self.force_fw_configuration()

    @wrapper_decorator
    def _precondition(self, node):
        self._set_current_logs_dir(node)
        if self.current_iteration == "Iteration_1":
            self.firmware_downgrade(node)
            self.dnr_partition_check(node)
        self.remove_hwf_flag(node)

    @method_decorator()
    def select_proper_sw_to_activate(self, node):
        active_sw = node.get_active_sw()
        if active_sw.endswith(("T1", "T2")):
            node.target_sw_path = self.wft.target_sw_dict.get(f"{node.target_sw}_release_BTSSM_downloadable_A54")
        else:
            node.target_sw_path = self.wft.target_sw_dict.get(f"{node.target_sw}"
                                                              f"_release_BTSSM_downloadable_testpackage_T1_A54")

    def summary_operation(self, node, operation, failed_nodes):
        operation = "ACTIVATION"
        if failed_nodes:
            test_logger(f"Nodes failed during {operation}: {','.join(failed_nodes)}", "error")
            test_logger(f"[{node.node_alias}] {operation} RESET FAILED", "error")
            self.gather_mumin_logs_and_snapshot("update")
            if self.stop_test_after_fail:
                self.report_results_to_uuf_dashboard()
                raise FatalError(f"Test has been stopped, stop_test_after_fail is True")
        else:
            test_logger(f"[{node.node_alias}] {operation} RESET PASSED", hyperlink=True)
            if not self.passed_logs_gathered:
                self.gather_mumin_logs_and_snapshot("update")

    @function_wrapper
    def verify_active_sw(self):
        for node in self.test_nodes:
            self.check_active_sw(node, node.target_sw)
            node.source_sw = node.target_sw

    @method_decorator()
    def check_active_sw(self, node, expected_sw):
        if expected_sw:
            active_sw = node.get_active_sw()
            if expected_sw not in active_sw:
                raise FatalError(f"Expected software on BTS is different than requested\n"
                                 f"Current software: {active_sw}\n"
                                 f"Expected software: {expected_sw}")

    def check_source_and_target_sw(self):
        pass

    def set_sw_path_for_nodes(self):
        pass

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            if self.restore_sw:
                self.restore_from_testpackage()
            if self.force_fw_upgrade:
                self.restore_fw_update_flags()
        finally:
            super().test_teardown()

    def restore_from_testpackage(self):
        try:
            self.setup_admin_connections()
            for node in self.test_nodes:
                active_sw = node.get_active_sw()
                if active_sw.endswith(("T1", "T2")):
                    failed_nodes = self.update_sw_operation(node)
                    if failed_nodes:
                        raise TestFailedOnTeardownError
        finally:
            self.teardown_nodes()

    @method_decorator()
    def setup_wts(self):
        test_logger("Configuring WTS")
        try:
            wts_dict = {"wts_config": get_builtin_value("WTS_CONFIG"),
                        "edaemon_port": get_builtin_value("EDAEMON_PORT")}
            wts_configuration = {key: value for key, value in wts_dict.items() if value is not None}
            self.wts = WTS(**wts_configuration)
            self.wts.setup_edaemon_egate()
        except Exception as e:
            test_logger(e, "ERROR")
            raise WTSSetupError()

    @method_decorator()
    def execute_wts_reset(self):
        try:
            verify_function_x_times(3, 10, self.wts.reset_wts)
        except Exception as e:
            test_logger(e, "DEBUG")
            test_logger("Resetting WTS failed", "ERROR")
            raise WTSResetError()

    @method_decorator()
    def teardown_wts(self):
        try:
            self.wts.teardown_edaemon_egate()
        except Exception as e:
            test_logger(e, "ERROR")

    def precheck_method(self):
        self.clear_diagnostic_fault()
        try:
            self.multi_runner.start_watching_alarms_on_all_nodes()
        except NotAllOperationsSucceed as e:
            if "Alarms Watchdog cannot connect to BTS" in str(e):
                raise FatalError('Starting watchdog failed due to connection error with BTS')
        hw_timer = None if self.configure_wts else 10
        failed_nodes = self.multi_runner.verify_all_nodes(hw_timer, 0)
        if failed_nodes:
            self.precheck_failed = True
        return failed_nodes

    @method_decorator()
    def force_fw_configuration(self):
        def set_uboot_flags(slave_smod: bool = False):
            node.uboot_update_policy = node.ssh_manager.execute_command("uboot_env get update_policy",
                                                                        slave_smod=slave_smod)
            test_logger(f"Uboot_env update_policy: {node.uboot_update_policy}", "DEBUG")
            if node.uboot_update_policy != "update_policy=2":
                test_logger("Setting update_policy=2 on primary smod")
                node.ssh_manager.execute_command("uboot_env set update_policy=2", slave_smod=slave_smod)
                uboot_flags = node.ssh_manager.execute_command("uboot_env get", slave_smod=slave_smod)
                test_logger(f"Uboot env flags:\n {uboot_flags}", "DEBUG")

        for node in self.test_nodes:
            test_logger("Configuring force firmware upgrade")
            test_logger(f"Adding flag on smod: 0x20190=2")
            node.set_flags_on_smod(["0x20190=2"])
            set_uboot_flags()
            if node.ssh_manager.slave_smod:
                set_uboot_flags(True)
            node.force_fw_configured = True

    @method_decorator()
    def restore_fw_update_flags(self):
        def restore_flags(slave_smod: bool = False):
            swconfig = node.backup_swconfig_path_secondary_smod if slave_smod \
                else node.backup_swconfig_path_primary_smod
            node.put_swconfig_to_smod(swconfig, slave_smod=slave_smod)
            uboot_command = f"uboot_env set {node.uboot_update_policy}" if node.uboot_update_policy \
                else "uboot_env del update_policy"
            test_logger(f"{'Primary' if not slave_smod else 'Secondary'} uboot command: {uboot_command}", "DEBUG")
            node.ssh_manager.execute_command(uboot_command, slave_smod=slave_smod)

        test_logger("Restoring swconfig and update_policy")
        for node in self.test_nodes:
            restore_flags()
            if node.ssh_manager.slave_smod:
                restore_flags(True)

    @method_decorator()
    def select_upgrade_kpi(self, node):
        firmware_update_performed = node.check_if_firmware_changed_after_upgrade()
        if node.source_sw.split("_")[0] != node.target_sw.split("_")[0]:
            if firmware_update_performed or node.force_fw_configured:
                self.kpi_to_calculate = ["kpi2b", "kpi2k"]
            else:
                self.kpi_to_calculate = ["kpi2a", "kpi2k"]
        else:
            if firmware_update_performed or node.force_fw_configured:
                self.kpi_to_calculate = ["kpi2d"]
            else:
                self.kpi_to_calculate = ["kpi2c"]
        if self.additional_kpi:
            self.kpi_to_calculate += self.additional_kpi
            self.kpi_to_calculate = list(set(self.kpi_to_calculate))
        self.kpi.kpi_names = self.kpi_to_calculate
        if node.calculate_provision_download_kpi:
            self.kpi.kpi_names += ["kpi4a", "kpi4b", "KPISwDownload", "KPISwProvision"]
        test_logger(f"Selected KPI for upgrade calculation : {self.kpi_to_calculate}", "info")

    @method_decorator()
    def remove_hwf_flag(self, node):
        if node.remove_hwf_flag_if_exists():
            node.reset_site()
            self.configure_wts_if_needed(node)
            node.verify_node_bts_state()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.multi_runner.verify_all_nodes()

    @method_decorator()
    def configure_wts_if_needed(self, node):
        if self.configure_wts:
            for fault_id in ["7107", "7304", "7305", "7306"]:
                node.add_temporary_alarm(fault_id)
            node.verify_node_bts_state(check_cells=False)
            self.execute_wts_reset()

    def recovery_method(self, failed_node_instances):
        test_logger("Recovery check")
        self.multi_runner.start_log_tracing_all_nodes()
        state_results = self.multi_runner.run_operations_as_threads_and_return(
            failed_node_instances, Node.recovery_site_reset, check_cells=False)
        self.configure_wts_if_needed(self.test_nodes[0])
        self.multi_runner.start_watching_alarms_on_all_nodes()
        failed_nodes = self.multi_runner.verify_all_nodes(300, 0)
        self.multi_runner.stop_log_tracing_and_download_from_all_nodes(
            logs_dir=f"{self.current_logs_dir}/recovery_method")
        return {node for node in {*state_results["Failed"].keys(), *failed_nodes}}

    @method_decorator()
    def perform_uboot_downgrade(self, node):
        if not node.uboot_downgrade():
            return False
        if node.uboot.perform_reset:
            try:
                test_logger(f"[{node.node_alias}] Resetting site after uboot downgrade")
                node.reset_site()
                self.configure_wts_if_needed(node)
                node.verify_node_bts_state()
                node.start_watching_alarms()
                node.verify_node_state()
                if not node.recheck_uboot_results():
                    return False
                test_logger(f"[{node.node_alias}] UBOOT PASSED", hyperlink=True)
            except Exception as e:
                test_logger(e, "error")
                return False
        return True

    def perform_software_precheck(self, node):
        if self.software_precheck:
            return super().perform_software_precheck(node)
        return set()

    def set_target_sw_path(self, node):
        pass

    def live_update_precheck(self, node):
        pass

    def independent_sw_update(self, node):
        pass

    def set_calculate_provision_download_kpi(self, node):
        pass
